// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// REDSTONE SHOP SOCKETS (Redshelf ground-floor commercial spec, section 2). A socket is the space a shop's redstone
// gets: a 3-wide slot running back from the counter edge, a 1-wide wall line each side, on a 4-block bay. The building
// never fills it; it only fits it out (glass wall lines and back wall, a spawn-proof pit floor, the counter) and builds
// around it, so any benched machine (a Folio, 3 door stalls, a compact shop, a bulk buyer) drops in later and a tenant
// changes without the street front, party walls or upstairs moving.
//
//   layoutSockets({ face, at, floorY, units, rows, aisle })  -> layout (sockets.json): every socket's cells, in world
//   socketFitout(layout, { counter, glass, pit })            -> [[x,y,z,block,state]]  what the building places
//   reservedCells(layout)                                     -> Set "x,y,z" no part may write (runParts reserve)
//   checkSockets(grid, layout, { light })                     -> { ok, sockets: [{ id, kind, problems }], problems }
//
// Coordinates follow the spec: y 0 is the shop floor (world floorY), the counter edge is d 0 and the socket runs back
// to d -(depth-1); u runs along the street to the right as seen from it (brush-core frame()). `face` is the side the
// shop fronts look out of (toward the street), `at` the world cell at u 0 (the first wall line), the counter edge
// and the shop floor.
import { frame } from "./brush-core.mjs";

export const KINDS = {
  deep: { depth: 13, top: 6, hoppers: [1], takes: "a Folio (1:48 to 1:384, shulker-scale stock) or a compact shop" },
  shallow: { depth: 9, top: 5, hoppers: [0, 1, 2], takes: "3 door stalls (one per lane) or a bulk buyer" },
};
export const BOTTOM = -4, FLOOR_ABOVE = 7, BAY = 4, UNIT = ["deep", "shallow"];
const strip = (b) => String(b ?? "air").replace(/^minecraft:/, "");
const AIR = (b) => /(^|_)air$/.test(strip(b));
// non-conductors that close a wall line or a back wall: glass of any kind (the spec's light gray stained glass), and
// the transparent blocks redstone power can't pass through
const NONCONDUCTOR = /glass|leaves|slab$|stairs$|_wall$|fence|pane$|ice$|glowstone|sea_lantern|barrier/;
const CONDUCTS = (b) => !AIR(b) && !NONCONDUCTOR.test(strip(b));
const SPAWNPROOF = /glass|slab$|stairs$|carpet|leaves|_wall$|fence|pane$|barrier|hopper|trapdoor|ice$|bedrock|magma|_bars$/;
