      if (flags["no-contrast"]) o.contrast = false;
      if (flags.why != null && flags.why !== true) o.why = String(flags.why);
      if (flags.overhang != null && flags.overhang !== true) {
        const v = nums(flags.overhang);
        o.overhang = v.length === 4 ? { north: v[0], south: v[1], east: v[2], west: v[3] } : v[0];
        if (v.some((n) => !Number.isFinite(n) || n < 0)) die(`--overhang takes n or n,s,e,w (got ${flags.overhang})`);
        if (v.some((n) => n === 0) && !o.why) die("--overhang 0 removes the eave (no shadow line, no barge); give --why \"<reason from the concept>\" or use 1+");
      }
      if (flags.texture != null && flags.texture !== true) {
        if (flags.texture === "none") { o.texture = false; if (!o.why) die("--texture none makes a single flat roof plane; give --why \"<reason from the concept>\" or pick a palette"); }
        else o.material = flags.texture;
      }
      if (o.contrast === false && !o.why) die("--no-contrast / contrast:false disables the roof-vs-wall tone check; give --why \"<reason from the concept>\"");
      if (flags["dry-run"]) o.dryRun = true;
      if (flags.lower != null) o.lower = Number(flags.lower);
      if (flags.y != null) o.y = Number(flags.y);
      if (flags.footprint) o.footprint = String(flags.footprint).split(";").map(nums);
      if (flags.dormers) { const [n, f, st] = String(flags.dormers).split(":"); o.dormers = { count: Number(n), face: FACE[f] || f || "south", ...(st ? { style: st } : {}) }; }
      if (flags.pediment) o.pediment = { face: FACE[flags.pediment] || flags.pediment, ...(spec.pediment || {}) };
      if (flags.tower) { const [x, z, w, h, top] = String(flags.tower).split(","); o.tower = { at: [Number(x), Number(z)], size: Number(w), height: Number(h), top: top || "lantern" }; }
      if (flags.chimney) o.chimneys = [...(o.chimneys || []), { at: nums(flags.chimney) }];
      if (o.preset && !ROOF_PRESETS[o.preset]) die(`unknown preset ${o.preset} (${Object.keys(ROOF_PRESETS).join(", ")})`);
      if (!o.preset && !ROOF_STYLES.includes(o.style || "hip")) die(`unknown style ${o.style} (${ROOF_STYLES.join(", ")})`);
      const dry = !!flags["dry-run"];
      const r = reroof(g, o);
      if (!dry) g.save(pos[1]);
      const review = r.facts ? reviewRoof(r.facts, o) : null;
      const res = { out: dry ? undefined : pos[1], dryRun: dry || undefined, preset: o.preset, style: o.style || (o.preset ? undefined : "hip"), detected: r.detected, cells: r.cells, refused: r.refused, shift: r.shift, top: r.top, notes: r.notes,
        ...(review ? { facts: r.facts, warnings: review.warnings, lookNotes: review.lookNotes } : {}) };
      if (flags.json) { out(res); if (flags.strict && review && !review.ok) process.exit(2); return; }
      console.log(`detected: eave y=${r.detected.eave} (roof from y=${r.detected.y}), footprint ${r.detected.rects.map((q) => `[${q}]`).join(" ")}, removed ${r.detected.removed} old roof blocks`);
      for (const n of r.notes || []) console.log(`note: ${n}`);
      if (dry) console.log(`dry run ${res.preset ? `preset ${res.preset}` : res.style}: nothing written`);
      else console.log(`built ${res.preset ? `preset ${res.preset}` : res.style}: ${r.cells} cells${r.refused ? `, ${r.refused} refused (protected/keep)` : ""}; roof top y=${r.top}${r.shift?.some(Boolean) ? `; the box grew, everything moved by ${r.shift}` : ""}`);
      if (review) console.log(review.report);
      if (!dry) console.log(`# saved ${pos[1]}`);
      if (flags.strict && review && !review.ok) process.exit(2);
      return;
    }
