        if (xyz(flags.at)[1] < 5) die(`sockets layout: the shop floor y ${xyz(flags.at)[1]} is too low: the boxes reach 4 below it and the ground 5, and the build's y starts at 0. Use y 5 or more (raise the whole build: road at y-1, sidewalk, shop floor).`);
        const L = S.layoutSockets({ face: flags.face || "south", at: xyz(flags.at), units: /^\d+$/.test(String(flags.units ?? "1")) ? +(flags.units ?? 1) : flags.units, rows: +(flags.rows || 1), aisle: +(flags.aisle ?? 2) });
        const off = L.sockets.flatMap((s) => [s.box.from, s.box.to]).find((c) => c[0] < 0 || c[2] < 0 || c[1] < 0);
        if (off) die(`sockets layout: a box reaches ${off.join(",")}, off the grid (x, y and z start at 0). A row runs to the street's right as seen from the street: facing north that is toward -x, facing south +x, east +z, west -z. Move --at.`);
        if (flags.out) { writeFileSync(resolve(flags.out), JSON.stringify(L, null, 1)); }
        const span = (s) => `${s.box.from.join(",")} .. ${s.box.to.join(",")}`;
